platforms2.text:
playsound minecraft:entity.experience_orb.pickup master @a ~ ~ ~ 10 2 1
tellraw @a {fallback:"Win the diamonds on the platforms by selecting that platform.",translate:"mcp.platforms2.1",color:"dark_aqua",type:"translatable"}
schedule function mcp:platforms3 3s

platforms3.text:
playsound minecraft:entity.experience_orb.pickup master @a ~ ~ ~ 10 2 1
tellraw @a {fallback:"If another player chooses the same platform, then neither of you win the diamonds.",translate:"mcp.platforms3.1",color:"dark_green",type:"translatable"}
schedule function mcp:platforms4 3s

platforms4.text:
playsound minecraft:entity.experience_orb.pickup master @a ~ ~ ~ 10 2 1
tellraw @a {fallback:"Earn the most diamonds to win!",translate:"mcp.platforms4.1",color:"dark_aqua",type:"translatable"}
schedule function mcp:ready_up_tellraw 3s

platforms_jump.text:
playsound minecraft:block.bell.use master @a ~ ~ ~ 10 0 1
execute at @e[tag=spotA] run tp @e[distance=0..0] ~ ~ ~
execute at @e[tag=spotB] run tp @e[distance=0..0] ~ ~ ~
execute at @e[tag=spotC] run tp @e[distance=0..0] ~ ~ ~
execute at @e[tag=spotD] run tp @e[distance=0..0] ~ ~ ~

execute at @e[tag=spotA] run scoreboard players set @p[distance=0..2] spotA 1
execute at @e[tag=spotB] run scoreboard players set @p[distance=0..2] spotB 1
execute at @e[tag=spotC] run scoreboard players set @p[distance=0..2] spotC 1
execute at @e[tag=spotD] run scoreboard players set @p[distance=0..2] spotD 1
effect clear @a minecraft:invisibility

scoreboard players set inair variables 1
#gets rid of barriers and walls in arena
fill -2 47 -42 -12 45 -52 minecraft:air replace minecraft:barrier
scoreboard players set @a knocked 0

execute if score spotA variables matches 1 run data merge entity @e[tag=spotA,limit=1] {Motion:[0.0d,1.0d,-0.6d]}
execute if score spotA variables matches 2 run data merge entity @e[tag=spotA,limit=1] {Motion:[0.6d,1.0d,0.0d]}
execute if score spotA variables matches 3 run data merge entity @e[tag=spotA,limit=1] {Motion:[0.0d,1.0d,0.6d]}
execute if score spotB variables matches 1 run data merge entity @e[tag=spotB,limit=1] {Motion:[-0.6d,1.0d,0.0d]}
execute if score spotB variables matches 2 run data merge entity @e[tag=spotB,limit=1] {Motion:[0.0d,1.0d,-0.6d]}
execute if score spotB variables matches 3 run data merge entity @e[tag=spotB,limit=1] {Motion:[0.6d,1.0d,0.0d]}
execute if score spotC variables matches 1 run data merge entity @e[tag=spotC,limit=1] {Motion:[0.0d,1.0d,0.6d]}
execute if score spotC variables matches 2 run data merge entity @e[tag=spotC,limit=1] {Motion:[-0.6d,1.0d,0.0d]}
execute if score spotC variables matches 3 run data merge entity @e[tag=spotC,limit=1] {Motion:[0.0d,1.0d,-0.6d]}
execute if score spotD variables matches 1 run data merge entity @e[tag=spotD,limit=1] {Motion:[0.6d,1.0d,0.0d]}
execute if score spotD variables matches 2 run data merge entity @e[tag=spotD,limit=1] {Motion:[0.0d,1.0d,0.6d]}
execute if score spotD variables matches 3 run data merge entity @e[tag=spotD,limit=1] {Motion:[-0.6d,1.0d,0.0d]}

schedule function mcp:platforms_jump2 104t

platforms_rules.text:
scoreboard players add currentRule variables 1
playsound minecraft:entity.experience_orb.pickup master @a ~ ~ ~ 10 2 1
execute if score currentRule variables matches 1 run tellraw @a {fallback:"Win the diamonds on the platforms by selecting that platform.",translate:"mcp.platforms_rules.1",color:"dark_aqua",type:"translatable"}
execute if score currentRule variables matches 2 run tellraw @a {fallback:"If another player chooses the same platform, then neither of you win the diamonds.",translate:"mcp.platforms_rules.2",color:"dark_green",type:"translatable"}
execute if score currentRule variables matches 3 run tellraw @a {fallback:"Earn the most diamonds to win!",translate:"mcp.platforms_rules.3",color:"dark_aqua",type:"translatable"}
execute if score currentRule variables matches 1..3 run schedule function mcp:platforms_rules 3s
execute if score currentRule variables matches 4 run function mcp:ready_up_tellraw

