monster_shoot_rules.text:
scoreboard players add currentRule variables 1
playsound minecraft:entity.experience_orb.pickup master @a ~ ~ ~ 10 2 1
execute if score currentRule variables matches 1 run function mcp:give_ready_ups
execute if score currentRule variables matches 1 if score players variables matches 5.. run scoreboard players set radius variables 12
execute if score currentRule variables matches 1 if score players variables matches 5.. positioned -72 19 -263 run function mcp:player_circle
execute if score currentRule variables matches 1 run tellraw @a {fallback:"The point values are as follows:",translate:"mcp.monster_shoot_rules.1",color:"dark_aqua",type:"translatable"}
execute if score currentRule variables matches 2 run tellraw @a {fallback:"Zombie: 1 Point\nCreeper: 2 Points\nSkeleton: 3 Points\nSilverfish: 5 Points",translate:"mcp.monster_shoot_rules.2",color:"dark_green",type:"translatable"}
execute if score currentRule variables matches 3 run tellraw @a {fallback:"The game ends after 60 seconds. Earn the most points to win!",translate:"mcp.monster_shoot_rules.3",color:"dark_aqua",type:"translatable"}
execute if score currentRule variables matches 1..3 run schedule function mcp:monster_shoot_rules 3s
execute if score currentRule variables matches 4 run function mcp:ready_up_tellraw

ms_spawn_monster.text:
tag @e[type=minecraft:item,tag=ms_monster,sort=random,limit=1] add temp
execute as @e[type=minecraft:item,tag=temp,tag=zombie] as @e[type=minecraft:item,tag=monster_shoot,sort=random,limit=1] at @s run summon minecraft:chicken ~ 55 ~ {NoGravity:0b,Silent:1b,PersistenceRequired:1b,Health:5.0f,Tags:["z"],Passengers:[{id:"minecraft:zombie",Silent:1b,PersistenceRequired:1b,Health:5.0f,Tags:["z","monster"],attributes:[{id:"minecraft:max_health",base:5.0d}],equipment:{head:{id:"minecraft:stone_button",count:1}}}],active_effects:[{id:"minecraft:invisibility",duration:999999,show_particles:0b}],attributes:[{id:"minecraft:max_health",base:5.0d},{id:"minecraft:knockback_resistance",base:1.0d}]}
execute as @e[type=minecraft:item,tag=temp,tag=creeper] as @e[type=minecraft:item,tag=monster_shoot,sort=random,limit=1] at @s run summon minecraft:creeper ~ 55 ~ {Tags:["monster"],Silent:1b,Health:5.0f,attributes:[{id:"minecraft:max_health",base:5.0d}]}
execute as @e[type=minecraft:item,tag=temp,tag=skeleton] as @e[type=minecraft:item,tag=monster_shoot,sort=random,limit=1] at @s run summon minecraft:skeleton ~ 55 ~ {Tags:["monster"],Silent:1b,Health:5.0f,attributes:[{id:"minecraft:max_health",base:5.0d}],equipment:{head:{id:"minecraft:stone_button",count:1}}}
execute as @e[type=minecraft:item,tag=temp,tag=silverfish] as @e[type=minecraft:item,tag=monster_shoot,sort=random,limit=1] at @s run summon minecraft:silverfish ~ 55 ~ {Tags:["monster"],Silent:1b,Health:5.0f,attributes:[{id:"minecraft:max_health",base:5.0d}]}

execute if entity @e[tag=zombie,tag=temp,type=item] run scoreboard players add ms_total variables 1
execute if entity @e[tag=creeper,tag=temp,type=item] run scoreboard players add ms_total variables 2
execute if entity @e[tag=skeleton,tag=temp,type=item] run scoreboard players add ms_total variables 3
execute if entity @e[tag=silverfish,tag=temp,type=item] run scoreboard players add ms_total variables 5

tag @e remove temp
scoreboard players set spawn_cycle variables 0
